class Solution {
public:
    int countPalindromicSubsequences(string s) {
        int n = s.size();
        if (n == 0) return 0;
        const long long MOD = 1000000007;

        // next[i][c] = smallest index >= i with s[index] == c, or n if none
        vector<vector<int>> nxt(n + 1, vector<int>(4, n));
        for (int i = n - 1; i >= 0; i--) {
            for (int c = 0; c < 4; c++) nxt[i][c] = nxt[i + 1][c];
            nxt[i][s[i] - 'a'] = i;
        }
        // prev[i][c] = largest index <= i with s[index] == c, or -1 if none
        vector<vector<int>> prv(n, vector<int>(4, -1));
        for (int i = 0; i < n; i++) {
            if (i > 0)
                for (int c = 0; c < 4; c++) prv[i][c] = prv[i - 1][c];
            prv[i][s[i] - 'a'] = i;
        }

        vector<vector<long long>> dp(n, vector<long long>(n, 0));
        for (int i = 0; i < n; i++) dp[i][i] = 1;

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len <= n; i++) {
                int j = i + len - 1;
                if (s[i] != s[j]) {
                    dp[i][j] = (dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1] + MOD) % MOD;
                } else {
                    int c = s[i] - 'a';
                    int low = nxt[i + 1][c];
                    int high = prv[j - 1][c];
                    if (low > high) {
                        dp[i][j] = (2 * dp[i + 1][j - 1] + 2) % MOD;
                    } else if (low == high) {
                        dp[i][j] = (2 * dp[i + 1][j - 1] + 1) % MOD;
                    } else {
                        dp[i][j] = (2 * dp[i + 1][j - 1] - dp[low + 1][high - 1] + MOD) % MOD;
                    }
                }
            }
        }
        return (int)dp[0][n - 1];
    }
};
